void mbc_36ksm::predict(const BallCandidates::PatchYUVClassified& patch, double meanBrightnessOffset)
{
	ASSERT(patch.size() == 16);

	for(size_t x=0; x < patch.size(); x++) {
		for(size_t y=0; y < patch.size(); y++) {
			// Add a custom brightness offset that depends on the dataset, if zero centering was used
			float value = (static_cast<float>((patch.data[patch.size() * x + y].pixel.y)) / 255.0f) + static_cast<float>(meanBrightnessOffset);
			in_step[y][x][0] = value;
		}
	}

	cnn(in_step);
}

double mbc_36ksm::getRadius() const {
	return 1.0;
}

Vector2d mbc_36ksm::getCenter() const {
	return Vector2d(0.5, 0.5);
}

double mbc_36ksm::getBallConfidence() const {
	return scores[1];
}

